/**
 * Storage abstraction. Local filesystem now; an object store can implement the
 * same three methods later. Keys are generated by the app (UUID-based) and
 * are re-checked here so a crafted key can never escape the storage root.
 */
import fs from "node:fs";
import path from "node:path";
import { getConfig } from "./config";

export interface BlobStorage {
  put(key: string, data: Buffer | string): Promise<void>;
  get(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
}

const KEY_RE = /^[a-z0-9-]+(\/[a-z0-9-]+)*(\.[a-z0-9]{1,8})?$/;

export class LocalStorage implements BlobStorage {
  constructor(private root: string) {}

  resolve(key: string): string {
    if (!KEY_RE.test(key)) throw new Error("Invalid storage key");
    const full = path.resolve(this.root, key);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Invalid storage key");
    return full;
  }

  async put(key: string, data: Buffer | string) {
    const full = this.resolve(key);
    await fs.promises.mkdir(path.dirname(full), { recursive: true });
    await fs.promises.writeFile(full, data);
  }

  async get(key: string) {
    return fs.promises.readFile(this.resolve(key));
  }

  async delete(key: string) {
    await fs.promises.rm(this.resolve(key), { force: true });
  }
}

let storage: LocalStorage | null = null;
export function getStorage(): LocalStorage {
  if (!storage) storage = new LocalStorage(getConfig().storageDir);
  return storage;
}
